import type { ComboboxItemProps } from "../combobox.types";

import { forwardRef } from "react";
import { ComboboxOption } from "@headlessui/react";
import { clsx } from "clsx";
import { Check as CheckIcon } from "@exp-textura/icons";

import { useComboboxState } from "../hooks/use-combobox-state";
import { ComboboxClasses } from "../combobox.styles";

const ComboboxItem = forwardRef<HTMLLIElement, ComboboxItemProps>(
  ({ children, value, className, ...restProps }, ref) => {
    const { showSelectedIndicator } = useComboboxState();

    return (
      <ComboboxOption
        ref={ref}
        className={({ focus, selected }) =>
          clsx(ComboboxClasses.item, className, {
            [ComboboxClasses.itemActive]: focus,
            [ComboboxClasses.itemSelected]: selected,
          })
        }
        value={value}
        {...restProps}
      >
        {({ selected }) => (
          <>
            {showSelectedIndicator && selected && <CheckIcon />}
            {children}
          </>
        )}
      </ComboboxOption>
    );
  },
);

ComboboxItem.displayName = "Combobox.Item";

export { ComboboxItem };
